'use strict';

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { loadConfig } = require('./config-loader');

function writeTempConfig(content) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-loader-'));
  const filePath = path.join(dir, 'config.json');
  fs.writeFileSync(filePath, content);
  return filePath;
}

test('returns defaults when the file is missing', () => {
  const merged = loadConfig('/nonexistent/nope.json', { port: 8080 });
  assert.deepStrictEqual(merged, { port: 8080 });
});

test('merges defaults with user values', () => {
  const file = writeTempConfig(JSON.stringify({ host: 'example.com' }));
  const merged = loadConfig(file, { port: 8080, retries: 3 });
  assert.deepStrictEqual(merged, { port: 8080, retries: 3, host: 'example.com' });
});

test('overwrites user values with defaults when they conflict', () => {
  const file = writeTempConfig(JSON.stringify({ port: 3000 }));
  const merged = loadConfig(file, { port: 8080, host: 'localhost' });
  assert.deepStrictEqual(merged, { port: 8080, host: 'localhost' });
});
